// OWNER: A1 content-migrator. Typed access to content/media-manifest.json (generated by scripts/migrate-media.ts).
import type { MediaEntry, MediaRef } from "../lib/content/types";
import added from "./media-added.json";
import manifest from "./media-manifest.json";

// media-added.json: photos added by hand after the migration (real stay shoots). Listed first so /gallery and the home mosaic lead with them.
export const mediaManifest: MediaEntry[] = [...added, ...manifest];

/** MediaRef for a manifest id. Throws at build time on a typo so broken images never ship. */
export function media(id: string): MediaRef {
  const m = mediaManifest.find((x) => x.id === id);
  if (!m) throw new Error(`Unknown media id "${id}" (see content/media-manifest.json)`);
  return { src: m.src, alt: m.alt, width: m.width, height: m.height, blurDataURL: m.blurDataURL };
}

/** Photos free of baked-in text (the legacy gallery and every added stay shoot); use these where text sits over an image. */
export const CLEAN_PHOTOS = mediaManifest.filter((m) => !m.hasBakedText).map((m) => m.id);

// Gold mark (pin, wordmark, house) on transparent, for structured data. The header builds the logo from
// separate layers (components/layout/BrandLogo.tsx) with the tagline as live text.
export const LOGO: MediaRef = { src: "/media/brand/logo-mark.png", alt: "Stay Story", width: 366, height: 137 };
